19	/**
20	 * ValidationGate is a pluggable RxJava FlowableTransformer that validates inbound {@link LearningRecord}s
21	 * against a pre-configured list of {@link ValidationRule rules}.  Each record is validated in isolation
22	 * (stateless) and emits a {@link ValidationResult}, ensuring that downstream consumers can decide how to
23	 * handle warnings or failures (e.g. retry, dead-letter queue, UI notification).
24	 *
25	 * <p>Example usage:
26	 * <pre>{@code
27	 * List<ValidationRule> rules = Arrays.asList(
28	 *     new ScoreWithinRangeRule(0, 100),
29	 *     new NonNullFieldRule("studentId"),
30	 *     new CurriculumStandardRule(standardRepository)
31	 * );
32	 *
33	 * Flowable<LearningRecord> source = kafkaSource.receive();
34	 * Flowable<ValidationGate.ValidationResult> validated = source.compose(new ValidationGate(rules));
35	 * validated.subscribe(sink::process);
36	 * }</pre>
37	 *
38	 * The gate also exposes a shallow metric stream ({@link #metrics()}) that can be wired to a dashboard.
39	 */
40	public class ValidationGate implements FlowableTransformer<LearningRecord, ValidationGate.ValidationResult> {
41	
42	    private static final Logger LOGGER = LoggerFactory.getLogger(ValidationGate.class);
43	
44	    /**
45	     * Immutable result of a validation attempt.
46	     */
47	    public static final class ValidationResult {
48	        public enum Status {PASSED, WARNING, FAILED}
49	
50	        private final LearningRecord record;
51	        private final Status status;
52	        private final List<ValidationError> errors;
53	        private final Instant validatedAt;
54	
55	        private ValidationResult(LearningRecord record, Status status, List<ValidationError> errors) {
56	            this.record = record;
57	            this.status = status;
58	            this.errors = errors;
59	            this.validatedAt = Instant.now();
60	        }
61	
62	        public LearningRecord getRecord() {
63	            return record;
64	        }
65	
66	        public Status getStatus() {
67	            return status;
68	        }
69	
70	        public List<ValidationError> getErrors() {
71	            return Collections.unmodifiableList(errors);
72	        }
73	
74	        public Instant getValidatedAt() {
75	            return validatedAt;
76	        }
77	
78	        public boolean isSuccess() {
79	            return status == Status.PASSED || status == Status.WARNING;
80	        }
81	
82	        @Override
83	        public String toString() {
84	            return "ValidationResult{" +
85	                   "record=" + record +
86	                   ", status=" + status +
87	                   ", errors=" + errors +
88	                   ", validatedAt=" + validatedAt +
89	                   '}';
90	        }
91	    }
