95	     */
96	    public static final class ValidationError {
97	        private final String rule;
98	        private final String message;
99	
100	        public ValidationError(String rule, String message) {
101	            this.rule = rule;
102	            this.message = message;
103	        }
104	
105	        public String getRule() {
106	            return rule;
107	        }
108	
