121	     */
122	    @FunctionalInterface
123	    public interface ValidationRule {
124	        /**
125	         * @param record the record to be validated
126	         * @param errors a mutable list; implementors append {@link ValidationError}s here
127	         * @return true if the record passes the rule, false if it fails
128	         */
129	        boolean validate(LearningRecord record, List<ValidationError> errors);
130	    }
