132	    /**
133	     * Thread-safe live metrics for dashboarding.
134	     */
135	    public static final class Metrics {
136	        private final AtomicLong passed = new AtomicLong();
137	        private final AtomicLong warning = new AtomicLong();
138	        private final AtomicLong failed = new AtomicLong();
139	
140	        public long passed() { return passed.get(); }
141	        public long warning() { return warning.get(); }
142	        public long failed() { return failed.get(); }
143	
144	        private void inc(ValidationResult.Status status) {
145	            switch (status) {
146	                case PASSED -> passed.incrementAndGet();
147	                case WARNING -> warning.incrementAndGet();
148	                case FAILED -> failed.incrementAndGet();
149	                default -> { /* no-op */ }
150	            }
151	        }
152	
153	        @Override
154	        public String toString() {
155	            return "Metrics{" +
156	                   "passed=" + passed +
157	                   ", warning=" + warning +
158	                   ", failed=" + failed +
159	                   '}';
160	        }
161	    }
162	
163	    private final List<ValidationRule> rules;
164	    private final Metrics metrics = new Metrics();
165	    private final BehaviorSubject<Metrics> metricsSubject = BehaviorSubject.createDefault(metrics);
166	
167	    /**
168	     * @param rules Ordered list of validation rules.  Rules are executed sequentially.
169	     */
170	    public ValidationGate(List<ValidationRule> rules) {
171	        this.rules = new CopyOnWriteArrayList<>(Objects.requireNonNull(rules, "rules"));
172	    }
173	
174	    /**
175	     * Exposes live metrics for observer-based dashboards.
176	     */
177	    public Flowable<Metrics> metrics() {
178	        return metricsSubject.toFlowable(BackpressureStrategy.LATEST);
179	    }
180	
181	    /**
182	     * Add a rule at runtime. Thread-safe.
183	     */
184	    public void addRule(ValidationRule rule) {
185	        rules.add(Objects.requireNonNull(rule, "rule"));
186	    }
187	
188	    /**
189	     * Remove a rule at runtime. Thread-safe.
190	     */
191	    public void removeRule(Class<? extends ValidationRule> ruleClass) {
192	        rules.removeIf(r -> r.getClass().equals(ruleClass));
193	    }
194	
195	    /**
196	     * Core RxJava transformation: performs validation and emits {@link ValidationResult}s.
197	     */
198	    @Override
199	    public Flowable<ValidationResult> apply(Flowable<LearningRecord> upstream) {
200	        return upstream.map(record -> {
201	            List<ValidationError> errors = new ArrayList<>(4);
202	            boolean hardFail = false;
203	            boolean anyError = false;
204	
205	            for (ValidationRule rule : rules) {
206	                try {
207	                    boolean ok = rule.validate(record, errors);
208	                    if (!ok) {
209	                        anyError = true;
210	                        // A rule signals hard failure by returning false
211	                        hardFail = true;
212	                    }
213	                } catch (Exception ex) {
214	                    // Defensive: a bug in one rule must not kill the stream
215	                    LOGGER.error("Rule {} threw exception: {}", rule.getClass().getSimpleName(), ex.getMessage(), ex);
216	                    errors.add(new ValidationError(rule.getClass().getSimpleName(), "Exception: " + ex.getMessage()));
217	                    hardFail = true;
218	                }
219	            }
220	
221	            ValidationResult.Status status;
222	            if (hardFail) {
223	                status = ValidationResult.Status.FAILED;
224	            } else if (anyError) {
225	                status = ValidationResult.Status.WARNING;
226	            } else {
227	                status = ValidationResult.Status.PASSED;
228	            }
229	
230	            ValidationResult result = new ValidationResult(record, status, errors);
231	            metrics.inc(status);
232	            metricsSubject.onNext(metrics);
233	            return result;
234	        });
235	    }
