241	    /**
242	     * Ensures the record has a non-null field (uses reflection to avoid compile-time coupling).
243	     */
244	    public static class NonNullFieldRule implements ValidationRule {
245	        private final String field;
246	
247	        public NonNullFieldRule(String field) {
248	            this.field = Objects.requireNonNull(field, "field");
249	        }
250	
251	        @Override
252	        public boolean validate(LearningRecord record, List<ValidationError> errors) {
253	            try {
254	                Object value = record.getClass().getDeclaredField(field).get(record);
255	                if (value == null ||
256	                    (value instanceof CharSequence seq && seq.toString().isBlank())) {
257	                    errors.add(new ValidationError(getClass().getSimpleName(),
258	                                                   "Field '" + field + "' must not be null/blank"));
259	                    return false;
260	                }
261	                return true;
262	            } catch (NoSuchFieldException | IllegalAccessException e) {
263	                errors.add(new ValidationError(getClass().getSimpleName(),
264	                                               "Cannot access field '" + field + "': " + e.getMessage()));
265	                return false;
266	            }
267	        }
268	    }
269	
270	    /**
271	     * Validates assessment scores fall within an inclusive range.
272	     */
273	    public static class ScoreWithinRangeRule implements ValidationRule {
274	        private final double min;
275	        private final double max;
276	
277	        public ScoreWithinRangeRule(double min, double max) {
278	            if (min > max) throw new IllegalArgumentException("min>max");
279	            this.min = min;
280	            this.max = max;
281	        }
282	
283	        @Override
284	        public boolean validate(LearningRecord record, List<ValidationError> errors) {
285	            Double score = record.getScore();
286	            if (score == null) {
287	                // not all records have a score; treat as soft warning
288	                errors.add(new ValidationError(getClass().getSimpleName(),
289	                                               "Score is null (record type might not be an assessment)"));
290	                return true;
291	            }
292	            if (score < min || score > max) {
293	                errors.add(new ValidationError(getClass().getSimpleName(),
294	                                               "Score " + score + " outside range [" + min + "," + max + "]"));
295	                return false;
296	            }
297	            return true;
298	        }
299	    }
300	
301	    /**
302	     * Example rule that checks curriculum standards using an injected repository.
303	     * Demonstrates how rules can be stateful and depend on external systems.
