308	        public CurriculumStandardRule(CurriculumRepository repository) {
309	            this.repository = Objects.requireNonNull(repository, "repository");
310	        }
311	
312	        @Override
313	        public boolean validate(LearningRecord record, List<ValidationError> errors) {
314	            if (record.getStandardId() == null) {
315	                errors.add(new ValidationError(getClass().getSimpleName(),
