320	            if (!repository.exists(record.getStandardId())) {
321	                errors.add(new ValidationError(getClass().getSimpleName(),
322	                                               "Unknown curriculum standard: " + record.getStandardId()));
323	                return false;
324	            }
325	            return true;
326	        }
327	
328	        /**
329	         * Minimal interface to keep this file self-contained.
330	         */
331	        public interface CurriculumRepository {
332	            boolean exists(String standardId);
333	        }
334	    }
335	}

