24	/**
25	 * AnalyticsSink is the terminal stage of the EduStream Compass pipeline.
26	 * <p>
27	 * Responsibilities:
28	 * <ul>
29	 *     <li>Persist validated LearningRecord objects into an in-memory H2 database for ad-hoc queries.</li>
30	 *     <li>Maintain lightweight, in-memory aggregates (currently quiz averages).</li>
31	 *     <li>Publish aggregate snapshots to a Kafka topic for downstream consumers (e.g., dashboards).</li>
32	 *     <li>Notify an in-process {@link TeacherDashboard} observer every N records.</li>
33	 * </ul>
34	 *
35	 * The sink subscribes to a {@link Flowable} of {@link LearningRecord}s and handles back-pressure transparently
36	 * via {@link io.reactivex.subscribers.DefaultSubscriber}.
37	 */
38	public class AnalyticsSink extends DefaultSubscriber<LearningRecord> implements AutoCloseable {
39	
40	    private static final Logger LOGGER = LoggerFactory.getLogger(AnalyticsSink.class);
41	
42	    /* ---------- Configuration constants ---------- */
43	    private static final int BATCH_SIZE_FOR_DASHBOARD_PUSH = 25;
44	    private static final String INSERT_SQL =
45	            "INSERT INTO learning_records " +
46	                    "(record_id, learner_id, activity_id, activity_type, score, max_score, timestamp) " +
47	                    "VALUES (?, ?, ?, ?, ?, ?, ?)";
48	
49	    /* ---------- State ---------- */
50	    private final DataSource dataSource;
51	    private final Connection connection;
52	    private final PreparedStatement insertStmt;
53	    private final TeacherDashboard dashboard;
54	    private final KafkaProducer<String, String> kafkaProducer;
55	
56	    private final Map<String, QuizStats> quizStats = new ConcurrentHashMap<>();
57	    private final AtomicLong ingestedCount = new AtomicLong();
58	
59	    private volatile boolean closed = false;
60	
61	    /**
62	     * Builder for creating a fully-configured {@link AnalyticsSink}.
63	     */
64	    public static class Builder {
65	        private TeacherDashboard dashboard;
66	        private String kafkaBootstrapServers = "localhost:9092";
67	
68	        public Builder dashboard(TeacherDashboard dash) {
69	            this.dashboard = dash;
70	            return this;
71	        }
72	
73	        public Builder kafkaBootstrapServers(String servers) {
74	            this.kafkaBootstrapServers = Objects.requireNonNull(servers);
75	            return this;
76	        }
77	
78	        public AnalyticsSink build() throws SQLException {
79	            return new AnalyticsSink(dashboard, kafkaBootstrapServers);
80	        }
81	    }
82	
83	    private AnalyticsSink(TeacherDashboard dashboard, String kafkaBootstrapServers) throws SQLException {
84	        this.dashboard = Objects.requireNonNull(dashboard, "TeacherDashboard must not be null");
85	
86	        /* ---------- Configure H2 in-memory DB ---------- */
87	        dataSource = JdbcConnectionPool.create("jdbc:h2:mem:edustream;DB_CLOSE_DELAY=-1", "sa", "");
88	        connection = dataSource.getConnection();
89	        connection.setAutoCommit(true);
90	        connection.createStatement().execute(
91	                "CREATE TABLE IF NOT EXISTS learning_records (" +
92	                        "record_id VARCHAR(64) PRIMARY KEY, " +
93	                        "learner_id VARCHAR(64) NOT NULL, " +
94	                        "activity_id VARCHAR(64) NOT NULL, " +
95	                        "activity_type VARCHAR(32) NOT NULL, " +
96	                        "score DOUBLE, " +
97	                        "max_score DOUBLE, " +
98	                        "timestamp BIGINT NOT NULL)"
99	        );
100	        insertStmt = connection.prepareStatement(INSERT_SQL);
101	
102	        /* ---------- Configure Kafka producer ---------- */
103	        Properties kafkaProps = new Properties();
104	        kafkaProps.put("bootstrap.servers", Objects.requireNonNull(kafkaBootstrapServers));
105	        kafkaProps.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
106	        kafkaProps.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
107	        kafkaProducer = new KafkaProducer<>(kafkaProps);
108	
109	        LOGGER.info("AnalyticsSink initialized (Kafka @ {}, dashboard={})",
110	                kafkaBootstrapServers, dashboard.getClass().getSimpleName());
111	    }
112	
113	    /* ---------- RxJava Subscriber implementation ---------- */
114	
115	    @Override
116	    public void onNext(LearningRecord record) {
117	        if (closed) {
118	            LOGGER.warn("Received record after sink was closed: {}", record.getRecordId());
119	            return;
120	        }
121	
122	        try {
123	            persistRecord(record);
124	            updateAggregates(record);
125	        } catch (Exception ex) {
126	            LOGGER.error("Error processing LearningRecord {}", record.getRecordId(), ex);
127	            // We do not propagate error downstream; instead continue processing.
128	        }
129	
130	        long count = ingestedCount.incrementAndGet();
131	        if (count % BATCH_SIZE_FOR_DASHBOARD_PUSH == 0) {
132	            pushDashboardUpdate();
133	        }
134	    }
135	
136	    @Override
137	    public void onError(Throwable throwable) {
138	        LOGGER.error("AnalyticsSink upstream error", throwable);
139	        // In a production system we might trigger retries or circuit breakers.
140	    }
141	
142	    @Override
143	    public void onComplete() {
144	        LOGGER.info("Upstream completed. Flushing remaining aggregates.");
145	        pushDashboardUpdate();
146	        close();
147	    }
