149	    /* ---------- Public helper ---------- */
150	
151	    /**
152	     * Convenience method to attach this sink to a {@link Flowable}.
153	     */
154	    public void attachTo(Flowable<LearningRecord> flowable) {
155	        flowable.subscribe(this);
156	    }
