158	    /* ---------- Persistence & Aggregation helpers ---------- */
159	
160	    private void persistRecord(LearningRecord record) throws SQLException {
161	        insertStmt.setString(1, record.getRecordId());
162	        insertStmt.setString(2, record.getLearnerId());
163	        insertStmt.setString(3, record.getActivityId());
164	        insertStmt.setString(4, record.getActivityType().name());
165	        insertStmt.setDouble(5, record.getScore());
166	        insertStmt.setDouble(6, record.getMaxScore());
167	        insertStmt.setLong(7, record.getTimestamp());
168	        insertStmt.executeUpdate();
169	    }
170	
171	    private void updateAggregates(LearningRecord record) {
172	        if (record.getActivityType() != LearningRecord.ActivityType.QUIZ) {
173	            return;
174	        }
175	        quizStats.compute(record.getActivityId(), (quizId, stats) -> {
176	            if (stats == null) {
177	                stats = new QuizStats();
178	            }
179	            stats.totalScore += record.getScore();
180	            stats.submissionCount++;
181	            return stats;
182	        });
183	    }
184	
185	    private void pushDashboardUpdate() {
186	        try {
187	            DashboardSnapshot snapshot = createSnapshot();
188	            dashboard.update(snapshot);
189	            sendToKafka(snapshot);
190	        } catch (Exception ex) {
191	            LOGGER.error("Failed to push dashboard update", ex);
192	        }
193	    }
