195	    private DashboardSnapshot createSnapshot() {
196	        DashboardSnapshot snap = new DashboardSnapshot(Instant.now().toEpochMilli());
197	        for (Map.Entry<String, QuizStats> e : quizStats.entrySet()) {
198	            String quizId = e.getKey();
199	            QuizStats stats = e.getValue();
200	            snap.addQuizAverage(quizId, stats.getAverage());
201	        }
202	        return snap;
203	    }
204	
205	    private void sendToKafka(DashboardSnapshot snapshot) {
206	        String topic = "edu.analytics.dashboard";
207	        kafkaProducer.send(new ProducerRecord<>(topic, "snapshot", snapshot.toJson()), (metadata, exception) -> {
208	            if (exception != null) {
209	                LOGGER.error("Failed to send snapshot to Kafka", exception);
210	            }
211	        });
212	    }
213	
214	    /* ---------- Lifecycle ---------- */
215	
216	    @Override
217	    public void close() {
218	        if (closed) {
219	            return;
220	        }
221	        closed = true;
222	        try {
223	            kafkaProducer.flush();
224	            kafkaProducer.close();
225	        } catch (Exception ignored) {
226	        }
227	        try {
228	            insertStmt.close();
229	            connection.close();
230	        } catch (SQLException ignored) {
231	        }
232	        LOGGER.info("AnalyticsSink shut down ({} records ingested)", ingestedCount.get());
233	    }
234	
235	    /* ---------- Internal helper classes ---------- */
236	
237	    /**
238	     * Maintains running totals for a single quiz.
239	     */
240	    private static final class QuizStats {
241	        double totalScore = 0.0;
242	        long submissionCount = 0;
243	
244	        double getAverage() {
245	            return submissionCount == 0 ? 0 : totalScore / submissionCount;
246	        }
247	    }
248	
249	    /**
250	     * Immutable payload sent to dashboards.
251	     */
252	    public static final class DashboardSnapshot {
253	        private final long generatedAtMillis;
254	        private final Map<String, Double> quizAverages = new ConcurrentHashMap<>();
255	
256	        DashboardSnapshot(long generatedAtMillis) {
257	            this.generatedAtMillis = generatedAtMillis;
258	        }
259	
260	        void addQuizAverage(String quizId, double average) {
261	            quizAverages.put(quizId, average);
262	        }
263	
264	        public long getGeneratedAtMillis() {
265	            return generatedAtMillis;
266	        }
267	
268	        public Map<String, Double> getQuizAverages() {
269	            return quizAverages;
270	        }
271	
272	        public String toJson() {
273	            // Simple manual JSON construction to avoid external deps like Jackson
274	            StringBuilder sb = new StringBuilder("{");
275	            sb.append("\"generatedAtMillis\":").append(generatedAtMillis).append(',');
276	            sb.append("\"quizAverages\":{");
277	            int i = 0;
278	            for (Map.Entry<String, Double> e : quizAverages.entrySet()) {
279	                if (i++ > 0) sb.append(',');
280	                sb.append('"').append(e.getKey()).append('"').append(':').append(String.format("%.2f", e.getValue()));
281	            }
282	            sb.append("}}");
283	            return sb.toString();
284	        }
285	    }
286	}

