3	import io.reactivex.rxjava3.core.Observable;
4	import io.reactivex.rxjava3.schedulers.Schedulers;
5	import io.reactivex.rxjava3.subjects.PublishSubject;
6	import org.apache.kafka.clients.consumer.ConsumerConfig;
7	import org.apache.kafka.clients.consumer.ConsumerRecord;
8	import org.apache.kafka.clients.consumer.ConsumerRecords;
9	import org.apache.kafka.clients.consumer.KafkaConsumer;
10	import org.apache.kafka.common.errors.InterruptException;
11	import org.apache.kafka.common.errors.WakeupException;
12	
13	import java.io.Closeable;
14	import java.time.Duration;
15	import java.util.*;
16	import java.util.concurrent.*;
17	import java.util.concurrent.atomic.AtomicBoolean;
18	
19	/**
20	 * ClassroomEventSource is the first component of the EduStream Compass pipeline.
21	 * <p>
22	 * It is responsible for:
23	 * <ul>
24	 *     <li>Subscribing to Kafka topics that represent classroom event streams</li>
25	 *     <li>Transforming raw {@link ConsumerRecord}s into strongly-typed {@link RawClassroomEvent}s</li>
26	 *     <li>Publishing events downstream via an RxJava {@link Observable}</li>
27	 *     <li>Handling transient failures (e.g. network outages) using automatic reconnection with
28	 *     exponential back-off</li>
29	 * </ul>
30	 * <p>
31	 * The class is intentionally self-contained and can be re-used for unit/integration tests
32	 * by injecting a different Kafka bootstrap server or providing mock topics.
33	 */
34	public final class ClassroomEventSource implements Closeable {
35	
36	    /* --------  Static configuration defaults -------- */
37	    private static final Duration POLL_TIMEOUT = Duration.ofMillis(500);
38	    private static final int MAX_RETRIES = 5;
39	    private static final Duration INITIAL_BACKOFF = Duration.ofSeconds(1);
40	    private static final Duration MAX_BACKOFF = Duration.ofSeconds(30);
41	
42	    /* --------  instance state & concurrency primitives -------- */
43	    private final AtomicBoolean running = new AtomicBoolean(false);
44	    private final PublishSubject<RawClassroomEvent> eventSubject = PublishSubject.create();
45	
46	    /* --------  kafka & executor resources -------- */
47	    private final Properties consumerProps;
48	    private final Collection<String> topics;
49	    private final ExecutorService consumerExecutor =
50	            Executors.newSingleThreadExecutor(r -> new Thread(r, "classroom-event-consumer"));
51	    private final ScheduledExecutorService retryScheduler =
52	            Executors.newSingleThreadScheduledExecutor(r -> new Thread(r, "classroom-event-retry"));
53	
54	    private KafkaConsumer<String, String> consumer;
55	    private int retryAttempts = 0;
56	
57	    /* --------  Builder -------- */
58	    public static Builder builder() {
59	        return new Builder();
60	    }
61	
62	    private ClassroomEventSource(Properties consumerProps, Collection<String> topics) {
63	        this.consumerProps = consumerProps;
64	        this.topics = topics;
65	    }
66	
67	    /**
68	     * Starts the consumer loop in a dedicated thread. The first call to {@code start()} is a no-op if the
69	     * component is already running.
70	     */
71	    public void start() {
72	        if (running.compareAndSet(false, true)) {
73	            initializeConsumer();
74	            consumerExecutor.submit(this::consumeLoop);
75	        }
76	    }
77	
78	    /**
79	     * Exposes a hot {@link Observable}. Subscribers will immediately start receiving events after invoking
80	     * {@link #start()}. Errors inside the consumer loop are translated into onError signals, but the source will
81	     * attempt to recover automatically unless {@link #close()} has been invoked.
82	     */
83	    public Observable<RawClassroomEvent> getEventStream() {
84	        return eventSubject
85	                .hide()     // prevent downstream from accidentally mutating subject state
86	                .observeOn(Schedulers.io());
87	    }
88	
89	    /**
90	     * Close the Kafka consumer and shuts down internal thread pools gracefully.
91	     */
92	    @Override
93	    public void close() {
94	        if (running.compareAndSet(true, false)) {
95	            Optional.ofNullable(consumer).ifPresent(KafkaConsumer::wakeup); // break out of poll()
96	            shutdownAndAwait(consumerExecutor);
97	            shutdownAndAwait(retryScheduler);
98	            Optional.ofNullable(consumer).ifPresent(KafkaConsumer::close);
99	            eventSubject.onComplete();
100	        }
101	    }
102	
103	    /* ==========================================================================================
104	     *                                      Internal logic
105	     * ========================================================================================== */
106	
107	    private void initializeConsumer() {
108	        consumer = new KafkaConsumer<>(consumerProps);
109	        consumer.subscribe(topics);
110	    }
111	
112	    private void consumeLoop() {
113	        try {
114	            while (running.get()) {
115	                try {
116	                    final ConsumerRecords<String, String> records = consumer.poll(POLL_TIMEOUT);
117	                    for (ConsumerRecord<String, String> record : records) {
118	                        RawClassroomEvent event = mapToDomain(record);
119	                        eventSubject.onNext(event);
120	                    }
121	                    consumer.commitAsync();
122	                    retryAttempts = 0; // successful poll -> reset error counter
123	                } catch (WakeupException | InterruptException ex) {
124	                    if (running.get()) {
125	                        // treat as transient failure; attempt reconnection
126	                        handlePollFailure(ex);
127	                    } else {
128	                        // component is shutting down
129	                        break;
130	                    }
131	                } catch (Exception ex) {
132	                    // Unexpected exception; propagate downstream but try to keep the loop alive
133	                    eventSubject.onError(ex);
134	                    handlePollFailure(ex);
135	                }
136	            }
137	        } finally {
138	            Optional.ofNullable(consumer).ifPresent(KafkaConsumer::close);
139	        }
140	    }
141	
142	    private void handlePollFailure(Exception ex) {
143	        retryAttempts++;
144	        if (retryAttempts > MAX_RETRIES) {
145	            eventSubject.onError(new IllegalStateException(
146	                    "Exceeded maximum retry attempts (" + MAX_RETRIES + ") - giving up.", ex));
147	            close();
148	            return;
149	        }
150	
151	        long backoffMillis = calculateBackoff(retryAttempts, INITIAL_BACKOFF.toMillis(), MAX_BACKOFF.toMillis());
152	        retryScheduler.schedule(() -> {
153	            if (!running.get()) {
154	                return; // shutdown requested
155	            }
156	            try {
157	                Optional.ofNullable(consumer).ifPresent(KafkaConsumer::close);
158	                initializeConsumer(); // new consumer instance
159	            } catch (Exception reconnectEx) {
160	                // recursive retry if reconnection fails
161	                handlePollFailure(reconnectEx);
162	            }
163	        }, backoffMillis, TimeUnit.MILLISECONDS);
164	    }
165	
166	    private static long calculateBackoff(int attempt, long minMillis, long maxMillis) {
167	        long delay = (long) (minMillis * Math.pow(2, attempt - 1));
168	        return Math.min(delay, maxMillis);
169	    }
170	
171	    /**
172	     * Maps a raw Kafka {@link ConsumerRecord} into our domain-specific {@link RawClassroomEvent} format.
173	     * <p>
174	     * In a real-world implementation, this may involve parsing JSON/Avro payloads, performing lightweight
175	     * schema validation, or attaching metadata such as partition/offset for deduplication.  Here we only
176	     * showcase a trivial transformation.
177	     */
178	    private RawClassroomEvent mapToDomain(ConsumerRecord<String, String> record) {
179	        return new RawClassroomEvent(
180	                record.key() != null ? record.key() : "unknown-classroom",
181	                record.value(),
182	                record.timestamp(),
183	                record.topic(),
184	                record.partition(),
185	                record.offset()
186	        );
187	    }
188	
189	    private static void shutdownAndAwait(ExecutorService executor) {
190	        executor.shutdown();
191	        try {
192	            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
193	                executor.shutdownNow();
194	            }
195	        } catch (InterruptedException ie) {
196	            Thread.currentThread().interrupt();
197	            executor.shutdownNow();
198	        }
199	    }
200	
201	    /* ==========================================================================================
202	     *                                      Builder
203	     * ========================================================================================== */
204	
205	    public static final class Builder {
206	
207	        private final Properties properties = new Properties();
208	        private Collection<String> topics = new ArrayList<>();
209	
210	        private Builder() {
211	            // reasonable kafka defaults
212	            properties.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, "false");
213	            properties.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");
214	            properties.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG,
215	                    "org.apache.kafka.common.serialization.StringDeserializer");
216	            properties.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,
217	                    "org.apache.kafka.common.serialization.StringDeserializer");
218	        }
219	
220	        public Builder bootstrapServers(String commaSeparated) {
221	            properties.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, commaSeparated);
222	            return this;
223	        }
224	
225	        public Builder groupId(String groupId) {
226	            properties.put(ConsumerConfig.GROUP_ID_CONFIG, groupId);
227	            return this;
228	        }
229	
230	        public Builder withTopic(String topic) {
231	            this.topics.add(topic);
232	            return this;
233	        }
234	
235	        public Builder withTopics(Collection<String> topics) {
236	            this.topics = new ArrayList<>(topics);
237	            return this;
238	        }
239	
240	        public ClassroomEventSource build() {
241	            if (topics.isEmpty()) {
242	                throw new IllegalStateException("At least one topic must be configured");
243	            }
244	            Properties immutableProps = new Properties();
245	            immutableProps.putAll(properties);
246	            return new ClassroomEventSource(immutableProps, Collections.unmodifiableCollection(topics));
247	        }
248	    }
249	
250	    /* ==========================================================================================
251	     *                                      Domain Objects
252	     * ========================================================================================== */
253	
254	    /**
255	     * Represents the raw classroom event as it comes off the wire.  Later pipeline stages are
256	     * responsible for enriching, validating and transforming this into a {@code LearningRecord}.
257	     */
258	    public static final class RawClassroomEvent {
259	
260	        private final String classroomId;
261	        private final String payload; // raw JSON or CSV; format is opaque to this class
262	        private final long timestamp;
263	        private final String topic;
264	        private final int partition;
265	        private final long offset;
266	
267	        RawClassroomEvent(String classroomId,
268	                          String payload,
269	                          long timestamp,
270	                          String topic,
271	                          int partition,
272	                          long offset) {
273	            this.classroomId = classroomId;
274	            this.payload = payload;
275	            this.timestamp = timestamp;
276	            this.topic = topic;
277	            this.partition = partition;
278	            this.offset = offset;
279	        }
280	
281	        public String getClassroomId() {
282	            return classroomId;
283	        }
284	
285	        public String getPayload() {
286	            return payload;
287	        }
288	
289	        public long getTimestamp() {
290	            return timestamp;
291	        }
292	
293	        public String getTopic() {
294	            return topic;
295	        }
296	
297	        public int getPartition() {
298	            return partition;
299	        }
300	
301	        public long getOffset() {
302	            return offset;
303	        }
304	
305	        @Override
306	        public String toString() {
307	            return "RawClassroomEvent{" +
308	                    "classroomId='" + classroomId + '\'' +
309	                    ", timestamp=" + timestamp +
310	                    ", topic='" + topic + '\'' +
311	                    ", partition=" + partition +
312	                    ", offset=" + offset +
313	                    '}';
314	        }
315	
316	        @Override
317	        public int hashCode() {
318	            return Objects.hash(classroomId, timestamp, topic, partition, offset);
319	        }
320	
321	        @Override
322	        public boolean equals(Object obj) {
323	            if (!(obj instanceof RawClassroomEvent)) {
324	                return false;
325	            }
326	            RawClassroomEvent other = (RawClassroomEvent) obj;
327	            return Objects.equals(this.classroomId, other.classroomId)
328	                    && this.timestamp == other.timestamp
329	                    && Objects.equals(this.topic, other.topic)
330	                    && this.partition == other.partition
331	                    && this.offset == other.offset;
