2	
3	import com.edustream.compass.model.LearningRecord;
4	import com.edustream.compass.model.RawEvent;
5	import com.edustream.compass.quality.DataQualityException;
6	import com.edustream.compass.quality.QualityGate;
7	import com.edustream.compass.util.BackoffStrategy;
8	import com.edustream.compass.validation.ValidationResult;
9	import com.edustream.compass.validation.ValidationService;
10	import io.reactivex.Flowable;
11	import io.reactivex.FlowableTransformer;
12	import io.reactivex.functions.Function;
13	import io.reactivex.schedulers.Schedulers;
14	import org.reactivestreams.Publisher;
15	import org.slf4j.Logger;
16	import org.slf4j.LoggerFactory;
17	
18	import java.time.Duration;
19	import java.util.concurrent.TimeUnit;
20	
21	/**
22	 * Transformer component responsible for converting {@link RawEvent}s received
23	 * from upstream ClassroomEventSource instances into the canonical
24	 * {@link LearningRecord} format understood by downstream analytics consumers.
25	 *
26	 * The transformer performs the following steps for each incoming event:
27	 *  1. Syntactic & semantic validation via {@link ValidationService}
28	 *  2. Mapping to a LearningRecord using an injectable {@link RecordMapper}
29	 *  3. Field-level data-quality checks (range, completeness, timeliness)
30	 *  4. Emits the transformed record to the output {@link Flowable}
31	 *
32	 *  Malformed or irrevocably invalid events are redirected to the
33	 *  dead-letter sink configured on {@link #deadLetterSink}.  Transient
34	 *  failures (e.g. I/O when enriching an event) are retried with exponential
35	 *  back-off controlled by {@link BackoffStrategy}.
36	 *
37	 *  Threading model: – The transformer is fully non-blocking and relies on
38	 *  RxJava schedulers to parallelize CPU-bound mapping work while preserving
39	 *  the original event order per student-ID.
40	 */
41	public class Transformer implements FlowableTransformer<RawEvent, LearningRecord> {
42	
43	    private static final Logger LOG = LoggerFactory.getLogger(Transformer.class);
44	
45	    private final ValidationService validationService;
46	    private final QualityGate qualityGate;
47	    private final RecordMapper recordMapper;
48	    private final DeadLetterSink deadLetterSink;
49	    private final BackoffStrategy backoffStrategy;
50	
51	    /**
52	     * Constructs a new {@code Transformer}.
53	     *
54	     * @param validationService service used to validate raw events
55	     * @param qualityGate       data-quality rules to enforce
56	     * @param recordMapper      mapper converting raw events into LearningRecords
57	     * @param deadLetterSink    sink for unprocessable events
58	     * @param backoffStrategy   retry/back-off settings for transient failures
59	     */
60	    public Transformer(
61	            ValidationService validationService,
62	            QualityGate qualityGate,
63	            RecordMapper recordMapper,
64	            DeadLetterSink deadLetterSink,
65	            BackoffStrategy backoffStrategy) {
66	
67	        this.validationService = validationService;
68	        this.qualityGate = qualityGate;
69	        this.recordMapper = recordMapper;
70	        this.deadLetterSink = deadLetterSink;
71	        this.backoffStrategy = backoffStrategy;
72	    }
73	
74	    /**
75	     * Apply the transformer to the supplied upstream {@code Flowable}.
76	     *
77	     * The method is typically invoked implicitly by RxJava:
78	     * <pre>
79	     *     upstream.compose(new Transformer(...))
80	     * </pre>
81	     *
82	     * @param upstream stream emitting raw classroom events
83	     * @return a {@link Publisher} emitting valid LearningRecords
84	     */
85	    @Override
86	    public Publisher<LearningRecord> apply(Flowable<RawEvent> upstream) {
87	        return upstream
88	                /* Step 1 – Validation */
89	                .observeOn(Schedulers.computation())
90	                .flatMap(this::validateOrNack, /*maxConcurrency*/ 4)
91	
92	                /* Step 2 – Mapping */
93	                .map(recordMapper::map)
94	
95	                /* Step 3 – Data-quality enforcement */
96	                .map(this::enforceQuality)
97	
98	                /* Step 4 – Retry transient failures */
99	                .retryWhen(retryHandler())
100	
101	                /* Side-effect: log successfully transformed records */
102	                .doOnNext(record -> LOG.debug("Transformed record {}", record.getRecordId()))
103	                .onBackpressureBuffer();
104	    }
105	
106	    /**
107	     * Validate the provided event.  When the event is invalid the method
108	     * forwards it to the {@link DeadLetterSink} and produces an
109	     * {@code Flowable.empty()}, effectively dropping it from the pipeline.
110	     */
111	    private Publisher<RawEvent> validateOrNack(RawEvent event) {
112	        ValidationResult result = validationService.validate(event);
113	        if (result.isValid()) {
114	            return Flowable.just(event);
115	        }
116	
117	        // Dead-letter invalid event and continue without error
118	        deadLetterSink.publish(event, result.getErrorMessages());
119	        LOG.warn("Event [{}] failed validation and was sent to DLQ: {}",
120	                 event.getEventId(), result.getErrorMessages());
121	        return Flowable.empty();
122	    }
123	
124	    /**
125	     * Enforce data-quality rules against the candidate record.
126	     *
127	     * @throws DataQualityException when the record violates non-ignorable
128	     *                              quality constraints.
129	     */
130	    private LearningRecord enforceQuality(LearningRecord record) throws DataQualityException {
131	        qualityGate.check(record);
132	        return record;
133	    }
134	
135	    /**
136	     * Returns a function suitable for {@link Flowable#retryWhen(Function)}
137	     * that retries transient failures using the configured
138	     * {@link BackoffStrategy}.
139	     */
140	    private Function<Flowable<Throwable>, Publisher<?>> retryHandler() {
141	        return errors -> errors
142	                .zipWith(Flowable.range(1, backoffStrategy.getMaxRetries() + 1), RetrySignal::new)
143	                .flatMap(signal -> {
144	                    Throwable error = signal.error;
145	                    int attempt = signal.attempt;
146	
147	                    if (attempt > backoffStrategy.getMaxRetries()
148	                            || !isTransient(error)) {
149	                        // Propagate non-retriable or exhausted errors
150	                        return Flowable.error(error);
151	                    }
152	
153	                    Duration delay = backoffStrategy.delay(attempt);
154	                    LOG.info("Transient error detected (attempt {}/{}). Retrying in {} ms: {}",
155	                             attempt, backoffStrategy.getMaxRetries(),
156	                             delay.toMillis(), error.toString());
157	
158	                    return Flowable.timer(delay.toMillis(), TimeUnit.MILLISECONDS);
159	                });
160	    }
161	
162	    /**
163	     * Determines whether the supplied {@link Throwable} is considered a
164	     * transient failure (I/O, network, temporary DB outage, etc.).
165	     */
166	    private boolean isTransient(Throwable throwable) {
167	        // Keep it simple for now.  In production this would inspect exception
168	        // types or use a dedicated classifier.
169	        return throwable instanceof TransientException;
170	    }
171	
172	    /* --------------------------------------------------------------------- *
173	     * Helper *                                                               *
174	     * --------------------------------------------------------------------- */
175	
176	    private static final class RetrySignal {
177	        final Throwable error;
178	        final int attempt;
179	
180	        RetrySignal(Throwable error, int attempt) {
181	            this.error = error;
182	            this.attempt = attempt;
183	        }
184	    }
185	
186	    /* --------------------------------------------------------------------- *
187	     * Extension points *                                                     *
188	     * --------------------------------------------------------------------- */
189	
190	    /**
191	     * A simple contract for mapping raw events into LearningRecords.  A more
192	     * sophisticated implementation might delegate to MapStruct or leverage
193	     * reflection for dynamic formats.
194	     */
195	    @FunctionalInterface
196	    public interface RecordMapper {
197	        LearningRecord map(RawEvent event);
198	    }
199	
200	    /**
201	     * Dead-letter sink interface.  Typically backed by another Kafka topic or
202	     * an audit table inside the Compass DSL.
203	     */
204	    public interface DeadLetterSink {
205	        void publish(RawEvent event, String reason);
206	    }
207	
208	    /**
209	     * Marker interface designating an exception as transient / retriable.
210	     * Transient exceptions are subject to retry according to the configured
211	     * {@link BackoffStrategy}.
212	     */
213	    public interface TransientException {}
214	}

