155	        /**
156	         * Runs lightweight integrity checks and returns an Optional containing the first
157	         * validation failure encountered, or empty() if everything looks good.
158	         */
159	        public Optional<String> validate() {
160	            if (studentId == null || studentId.isBlank()) {
161	                return Optional.of("studentId must be set");
162	            }
163	            if (courseId == null || courseId.isBlank()) {
164	                return Optional.of("courseId must be set");
165	            }
166	            if (eventType == null) {
167	                return Optional.of("eventType must be provided");
168	            }
169	            if (eventType.isAssessment()) {
170	                if (score == null) {
171	                    return Optional.of("Assessment events must contain a score");
172	                }
173	                if (maxScore == null || maxScore <= 0) {
174	                    return Optional.of("Assessment events must have a positive maxScore");
175	                }
176	                if (score < 0 || score > maxScore) {
177	                    return Optional.of("score must be between 0 and maxScore inclusive");
178	                }
179	            }
180	            return Optional.empty();
181	        }
