183	        /**
184	         * Finalise the build process, throwing an IllegalStateException if the
185	         * record fails structural validation.
186	         */
187	        public LearningRecord build() {
188	            validate().ifPresent(err -> {
189	                throw new IllegalStateException("Invalid LearningRecord: " + err);
190	            });
191	            return new LearningRecord(
192	                    recordId, studentId, courseId, moduleId, eventType,
193	                    eventTime, score, maxScore, duration, qualityStatus, metadata
194	            );
195	        }
