200	    /**
201	     * Convenience method to evaluate whether the record represents a passing grade,
202	     * given a custom domain threshold (e.g., 0.7 = 70 %).
203	     *
204	     * Non-assessment records will always return {@code false}.
205	     */
206	    public boolean isPassing(double threshold) {
207	        if (!eventType.isAssessment() || score == null || maxScore == null) {
208	            return false;
209	        }
210	        return (score / maxScore) >= threshold;
