75	     * Start the streaming pipeline and register a shutdown hook.
76	     */
77	    public void start() {
78	        LOG.info("EduStream Compass starting …");
79	
80	        Observable<LearningEvent> classroomStream = createClassroomEventObservable(config);
81	        Observable<LearningEvent> validatedStream =
82	                classroomStream
83	                        .observeOn(Schedulers.computation())
84	                        .filter(this::validateEvent)
85	                        .compose(this::applyQualityGate);
86	
87	        Observable<LearningRecord> transformedStream =
88	                validatedStream.map(this::transformEvent);
89	
90	        Observable<Insight> analyticsStream =
91	                transformedStream
92	                        .buffer(config.getBatchSize())
93	                        .map(this::aggregateBatch)
94	                        .subscribeOn(Schedulers.computation());
95	
96	        // -------------------------------------------------------------
97	        // Sinks
98	        // -------------------------------------------------------------
99	        disposables.add(
100	                analyticsStream
101	                        .doOnNext(this::persistAnalytics)
102	                        .flatMap(this::toDashboardNotification)
103	                        .subscribe(
104	                                n -> LOG.debug("Published dashboard notification: {}", n),
105	                                err -> handleStreamError("analytics-stream", err)
106	                        )
107	        );
108	
109	        Runtime.getRuntime().addShutdownHook(new Thread(this::shutdown, "compass-shutdown"));
110	        LOG.info("EduStream Compass started.  Press Ctrl-C to stop.");
111	    }
