117	    /**
118	     * Create an Observable that continuously polls the classroom Kafka topic and emits LearningEvent
119	     * objects downstream.  The polling loop runs on its own daemon thread to avoid blocking RxJava’s
120	     * computation pool.
121	     */
122	    private Observable<LearningEvent> createClassroomEventObservable(ApplicationConfig cfg) {
123	
124	        Properties props = new Properties();
125	        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, cfg.getKafkaBootstrapServers());
126	        props.put(ConsumerConfig.GROUP_ID_CONFIG, cfg.getKafkaGroupId());
127	        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
128	        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
129	        props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");
130	
131	        return Observable.<LearningEvent>create(emitter -> {
132	            final KafkaConsumer<String, String> consumer = new KafkaConsumer<>(props);
133	            final AtomicBoolean cancelled = new AtomicBoolean(false);
134	            emitter.setCancellable(() -> {
135	                cancelled.set(true);
136	                consumer.wakeup();
137	            });
138	
139	            scheduler.submit(() -> {
140	                try (consumer) {
141	                    consumer.subscribe(Collections.singletonList(cfg.getSourceTopic()));
142	                    while (!cancelled.get()) {
143	                        ConsumerRecords<String, String> records = consumer.poll(KAFKA_POLL_INTERVAL);
144	                        for (ConsumerRecord<String, String> record : records) {
145	                            try {
146	                                LearningEvent event = MAPPER.readValue(record.value(), LearningEvent.class);
147	                                emitter.onNext(event);
148	                            } catch (JsonProcessingException ex) {
149	                                LOG.warn("Skipping unparsable record: {}", record.value(), ex);
150	                            }
151	                        }
152	                    }
153	                } catch (WakeupException we) {
154	                    // Expected on shutdown ‑ ignore.
155	                } catch (Throwable t) {
156	                    emitter.onError(t);
157	                }
158	            });
159	        }).share(); // multicast to downstream subscribers
160	    }
