1	package com.edustream.compass.pipeline;
2	
3	import io.reactivex.rxjava3.core.Flowable;
4	import io.reactivex.rxjava3.core.FlowableEmitter;
5	import io.reactivex.rxjava3.disposables.CompositeDisposable;
6	import io.reactivex.rxjava3.disposables.Disposable;
7	import io.reactivex.rxjava3.functions.Function;
8	import io.reactivex.rxjava3.processors.FlowableProcessor;
9	import io.reactivex.rxjava3.processors.PublishProcessor;
10	import io.reactivex.rxjava3.schedulers.Schedulers;
11	import org.reactivestreams.Publisher;
12	import org.slf4j.Logger;
13	import org.slf4j.LoggerFactory;
14	
15	import java.util.Objects;
16	import java.util.concurrent.TimeUnit;
17	
18	/**
19	 * Base class for every component in the EduStream Compass event-streaming pipeline.
20	 *
21	 * <p>It wires an upstream {@link Flowable} of {@code IN} events to a downstream
22	 * processor of {@code OUT} events, handles lifecycle management, basic retry
23	 * logic, error propagation, and exposes the resulting stream to observers.
24	 *
25	 * <p>Concrete implementations should focus solely on the transformation
26	 * logic by implementing {@link #build(Flowable)}.  All other operational
27	 * concerns are handled by this class.
28	 *
29	 * @param <IN>  Type of the incoming events
30	 * @param <OUT> Type of the outgoing events
31	 */
32	public abstract class PipelineComponent<IN, OUT> implements AutoCloseable {
33	
34	    /* --------------------------------------------------------------------- */
35	    /* Configuration                                                         */
36	    /* --------------------------------------------------------------------- */
37	
38	    /** Max number of automatic retries after a recoverable failure. */
39	    private final int maxRetryAttempts;
40	
41	    /** Delay between retries in milliseconds. */
42	    private final long retryDelayMillis;
43	
44	    /* --------------------------------------------------------------------- */
45	    /* State & Infrastructure                                                */
46	    /* --------------------------------------------------------------------- */
47	
48	    private final String componentName;
49	    private final Logger log;
50	    private final CompositeDisposable disposables = new CompositeDisposable();
51	    private final FlowableProcessor<OUT> outProcessor =
52	            PublishProcessor.<OUT>create().toSerialized();
53	
54	    private volatile boolean running = false;
55	
56	    /* --------------------------------------------------------------------- */
57	    /* Constructors                                                          */
58	    /* --------------------------------------------------------------------- */
59	
60	    /**
61	     * Create a new pipeline component with default retry policy
62	     * (3 attempts, 2 seconds between attempts).
63	     *
64	     * @param componentName logical name of the component (for logging/metrics)
65	     */
66	    protected PipelineComponent(final String componentName) {
67	        this(componentName, 3, TimeUnit.SECONDS.toMillis(2));
68	    }
69	
70	    /**
71	     * Create a new pipeline component with a custom retry policy.
72	     *
73	     * @param componentName    logical name of the component (for logging/metrics)
74	     * @param maxRetryAttempts how many times to retry a recoverable error
75	     * @param retryDelayMillis delay between retries in milliseconds
76	     */
77	    protected PipelineComponent(final String componentName,
78	                                final int maxRetryAttempts,
79	                                final long retryDelayMillis) {
80	
81	        this.componentName     = Objects.requireNonNullElse(
82	                componentName, getClass().getSimpleName());
83	        this.maxRetryAttempts  = Math.max(0, maxRetryAttempts);
84	        this.retryDelayMillis  = Math.max(0, retryDelayMillis);
85	        this.log               = LoggerFactory.getLogger(this.componentName);
86	    }
87	
88	    /* --------------------------------------------------------------------- */
89	    /* Public API                                                            */
90	    /* --------------------------------------------------------------------- */
91	
92	    /**
93	     * Start the component by subscribing to the given upstream flow.
94	     *
95	     * @param upstream the source stream
96	     */
97	    public final void start(final Flowable<IN> upstream) {
98	        Objects.requireNonNull(upstream, "Upstream Flowable must not be null");
99	
100	        if (running) {
101	            log.warn("{} already running – ignoring second start()", componentName);
102	            return;
103	        }
104	
105	        running = true;
106	
107	        // Build the transformation pipeline declared by the subclass.
108	        final Disposable subscription = build(upstream)
109	                .subscribeOn(Schedulers.io())      // read/compute on I/O threads
110	                .observeOn(Schedulers.io())         // push results on I/O threads
111	                .doOnNext(outProcessor::onNext)     // forward to observers
112	                .retryWhen(retryStrategy())         // simple retry policy
113	                .doFinally(this::stop)              // clean up on termination
114	                .subscribe(
115	                        ignored -> { /* handled in doOnNext */ },
116	                        this::handleTerminalError,
117	                        () -> log.info("{} completed", componentName)
118	                );
119	
120	        disposables.add(subscription);
121	        log.info("{} started", componentName);
122	    }
123	
124	    /**
125	     * The downstream stream emitted by this component.
126	     */
127	    public final Flowable<OUT> outputs() {
128	        return outProcessor.onBackpressureBuffer();
129	    }
130	
131	    /**
132	     * Whether the component is currently running.
133	     */
134	    public final boolean isRunning() {
135	        return running;
136	    }
137	
138	    /**
139	     * Stop the component and dispose of all resources.
140	     */
141	    public final void stop() {
142	        if (!running) {
143	            return;
144	        }
145	        log.info("{} stopping…", componentName);
146	        disposables.dispose();
147	        running = false;
148	        log.info("{} stopped", componentName);
149	    }
150	
151	    /**
152	     * Alias for {@link #stop()} so the component can be used with
153	     * try-with-resources.
154	     */
155	    @Override
156	    public final void close() {
157	        stop();
158	    }
159	
160	    /* --------------------------------------------------------------------- */
161	    /* To be implemented by subclasses                                       */
162	    /* --------------------------------------------------------------------- */
163	
164	    /**
165	     * Transform the incoming stream into the outgoing one.
166	     *
167	     * @param upstream upstream events
168	     * @return transformed downstream events
169	     */
170	    protected abstract Flowable<OUT> build(Flowable<IN> upstream);
171	
172	    /* --------------------------------------------------------------------- */
173	    /* Internal helpers                                                      */
174	    /* --------------------------------------------------------------------- */
175	
176	    /**
177	     * Simple exponential-backoff retry strategy.
178	     */
179	    private Function<Flowable<Throwable>, Publisher<Long>> retryStrategy() {
180	        return errors -> errors
181	                .zipWith(
182	                        Flowable.range(1, maxRetryAttempts + 1),
183	                        RetrySignal::new
184	                )
185	                .flatMap(signal -> {
186	                    if (signal.attempt > maxRetryAttempts) {
187	                        return Flowable.error(signal.error); // propagate
188	                    }
189	
190	                    long delay = retryDelayMillis * signal.attempt;
191	                    log.warn("{} caught exception (attempt {}/{}). Retrying in {} ms: {}",
192	                            componentName,
193	                            signal.attempt,
194	                            maxRetryAttempts,
195	                            delay,
196	                            signal.error.getMessage());
197	
198	                    return Flowable.timer(delay, TimeUnit.MILLISECONDS);
199	                });
200	    }
201	
202	    /**
203	     * Centralised terminal error handler.
204	     */
205	    private void handleTerminalError(Throwable t) {
206	        log.error("{} aborting after unrecoverable error", componentName, t);
207	        outProcessor.onError(t);
208	    }
209	
210	    /**
211	     * Tuple of (error, attempt no).
212	     */
213	    private static final class RetrySignal {
214	
215	        final Throwable error;
216	        final int attempt;
217	
218	        RetrySignal(Throwable error, int attempt) {
219	            this.error   = error;
220	            this.attempt = attempt;
221	        }
222	    }
223	}

